import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        edges.append((u, v, w, i))

    if m == n - 1:
        return

    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(i):
        path = []
        root = i
        while parent[root] != root:
            path.append(root)
            root = parent[root]
        for node in path:
            parent[node] = root
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    mst_edges_set = set()
    adj_mst = defaultdict(list)
    nodes_in_mst = [False] * (n + 1)

    count = 0
    for u, v, w, idx in sorted_edges:
        if union(u, v):
            mst_edges_set.add(idx)
            adj_mst[u].append((v, w))
            adj_mst[v].append((u, w))
            count += 1
            if count == n - 1:
                break

    non_mst_edges = []
    for u, v, w, idx in edges:
        if idx not in mst_edges_set:
            non_mst_edges.append((u, v, w, idx))

    results = {}

    def dfs_max_edge(start, target, exclude_idx=None):
        stack = [(start, -1, float('-inf'))]
        visited = set()
        visited.add(start)

        while stack:
            curr, prev, max_e = stack.pop()

            if curr == target:
                return max_e

            for neighbor, weight in adj_mst[curr]:
                if neighbor == prev:
                    continue
                if neighbor in visited:
                    continue

                current_max = max(max_e, weight)
                stack.append((neighbor, curr, current_max))

        return float('-inf')

    for u, v, w, idx in non_mst_edges:
        max_on_path = dfs_max_edge(u, v)
        results[idx] = max_on_path

    output_lines = []
    for u, v, w, idx in edges: 
        if idx not in mst_edges_set:
            val = results.get(idx, 0)
            if val == float('-inf'):
                val = 0
            output_lines.append(str(val))

    print('\n'.join(output_lines))

if __name__ == "__main__":
    main()
